package com.gerenciadorrural.modules.herd.infrastructure;
import com.gerenciadorrural.modules.herd.domain.*; import com.gerenciadorrural.shared.tenancy.TenantId; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Repository; import java.math.*; import java.time.*; import java.util.*;
@Repository public class JdbcHerdManagementRepository implements HerdManagementRepository {private final NamedParameterJdbcTemplate j; public JdbcHerdManagementRepository(NamedParameterJdbcTemplate j){this.j=j;} private MapSqlParameterSource p(TenantId t,UUID f,UUID a){return new MapSqlParameterSource().addValue("tenant",t.value()).addValue("farm",f).addValue("animal",a);}
 public Optional<String> operation(TenantId t,UUID f,UUID o){return j.query("select command_payload from app.herd_management_operations where tenant_id=:tenant and farm_id=:farm and operation_id=:op",p(t,f,o).addValue("op",o),(r,n)->r.getString(1)).stream().findFirst();} public void saveOperation(TenantId t,UUID f,UUID o,String type,String x){j.update("insert into app.herd_management_operations(tenant_id,farm_id,operation_id,command_type,command_payload) values(:tenant,:farm,:op,:type,:x)",p(t,f,o).addValue("op",o).addValue("type",type).addValue("x",x));}
 public void weight(TenantId t,UUID f,UUID a,UUID o,LocalDate d,BigDecimal k,String n,UUID actor){j.update("insert into app.animal_weight_measurements(id,tenant_id,farm_id,animal_id,operation_id,measured_on,weight_kg,notes,actor_user_id) values(:id,:tenant,:farm,:animal,:op,:d,:k,:n,:actor)",p(t,f,a).addValue("id",UUID.randomUUID()).addValue("op",o).addValue("d",d).addValue("k",k).addValue("n",n).addValue("actor",actor));}
 public void treatment(TenantId t,UUID f,UUID a,UUID o,HealthTreatmentType type,LocalDate d,String product,String protocol,LocalDate due,String n,UUID actor){j.update("insert into app.animal_health_treatments(id,tenant_id,farm_id,animal_id,operation_id,treatment_type,occurred_on,product,protocol,next_due_on,notes,actor_user_id) values(:id,:tenant,:farm,:animal,:op,:type,:d,:product,:protocol,:due,:n,:actor)",p(t,f,a).addValue("id",UUID.randomUUID()).addValue("op",o).addValue("type",type.name()).addValue("d",d).addValue("product",product).addValue("protocol",protocol).addValue("due",due).addValue("n",n).addValue("actor",actor));}
 public List<Weight> weights(TenantId t,UUID f,UUID a,int s,long o){return j.query("select id,operation_id,measured_on,weight_kg,notes,actor_user_id,recorded_at from app.animal_weight_measurements where tenant_id=:tenant and farm_id=:farm and animal_id=:animal order by measured_on desc,recorded_at desc,id desc limit :s offset :o",p(t,f,a).addValue("s",s).addValue("o",o),(r,n)->new Weight(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,LocalDate.class),r.getBigDecimal(4),r.getString(5),r.getObject(6,UUID.class),r.getObject(7,OffsetDateTime.class).toInstant()));} public long weightCount(TenantId t,UUID f,UUID a){return j.queryForObject("select count(*) from app.animal_weight_measurements where tenant_id=:tenant and farm_id=:farm and animal_id=:animal",p(t,f,a),Long.class);}
 public List<Treatment> treatments(TenantId t,UUID f,UUID a,int s,long o){return j.query("select id,operation_id,treatment_type,occurred_on,product,protocol,next_due_on,notes,actor_user_id,recorded_at from app.animal_health_treatments where tenant_id=:tenant and farm_id=:farm and animal_id=:animal order by occurred_on desc,recorded_at desc,id desc limit :s offset :o",p(t,f,a).addValue("s",s).addValue("o",o),(r,n)->new Treatment(r.getObject(1,UUID.class),r.getObject(2,UUID.class),HealthTreatmentType.valueOf(r.getString(3)),r.getObject(4,LocalDate.class),r.getString(5),r.getString(6),r.getObject(7,LocalDate.class),r.getString(8),r.getObject(9,UUID.class),r.getObject(10,OffsetDateTime.class).toInstant()));} public long treatmentCount(TenantId t,UUID f,UUID a){return j.queryForObject("select count(*) from app.animal_health_treatments where tenant_id=:tenant and farm_id=:farm and animal_id=:animal",p(t,f,a),Long.class);}}
